// ─── File: src/main/java/com/bank/event/listener/SmsListener.java ───
package com.bank.event.listener;

import org.springframework.scheduling.annotation.Async;
import org.springframework.transaction.event.TransactionPhase;
import org.springframework.transaction.event.TransactionalEventListener;
import org.springframework.stereotype.Component;

@Component
public class SmsListener {
    @Async
    @TransactionalEventListener(
        phase = TransactionPhase.AFTER_COMMIT,
        fallbackExecution = true)   // run even if there is no active transaction
    public void onTransferCommitted(TransferCompletedEvent e) {
        // only fires after a real commit; @Async keeps it off the request thread
    }
}
